MAX_BYTES = 1_048_576
DEFAULT_FIELD_MAP = {
    "material_code": "Material", "name": "MaterialDescription", "unit": "BaseUnit",
    "quantity": "Quantity", "stock": "UnrestrictedStock", "reserved_stock": "ReservedStock",
    "daily_consumption": "DailyConsumption", "lead_time_days": "LeadTimeDays",
