"""Local procurement request queue; it never connects to SAP or sends email.

The request owner's explicit, timezone-aware reply starts a collection window.
Saved question drafts are deliberately distinct from sent messages. A report is
prepared only after its file exists and the window has ended. SQLite transactions
make message replay and local concurrent monitor runs idempotent.
"""

from __future__ import annotations

import hashlib
import json
import os
import re
import sqlite3
import stat
import tempfile
from contextlib import contextmanager
from datetime import datetime, timezone
from decimal import Decimal, InvalidOperation
from pathlib import Path
from typing import Any

DEFAULT_PATH = Path.cwd() / ".codex/agents/satin-alma-stok/cases/requests.db"
EMAIL = re.compile(r"[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+")
SECRET_KEYS = {
    "apikey", "accesstoken", "refreshtoken", "token", "password", "secret",
    "clientsecret", "authorization", "headers", "credentials", "bearertoken",
}
OFFER_FIELDS = {
    "id", "request_id", "supplier", "email", "material_code", "material_name",
    "quantity", "unit", "currency", "cash_unit_price", "term_unit_price", "term_days",
    "vat_rate_pct", "vat_basis", "price_basis", "delivery_days", "technical_specs",
    "source_fields", "missing_fields",
}
EMAIL_FIELDS = {"message_id", "mailbox", "received_at", "sender", "subject", "body_excerpt", "source_url", "attachments"}
ATTACHMENT_FIELDS = {"attachment_id", "filename", "text_excerpt", "source_url", "sha256"}


def _text(value: Any, *, maximum: int = 500, required: bool = False) -> str | None:
    if value is None or value == "":
        if required:
            raise ValueError("Zorunlu metin alanı eksik")
        return None
    if not isinstance(value, str) or len(value) > maximum:
        raise ValueError("Metin alanı geçersiz veya çok uzun")
    value = value.strip()
    if required and not value:
        raise ValueError("Zorunlu metin alanı eksik")
    return value or None


def _email(value: Any, *, required: bool = False) -> str | None:
    value = _text(value, maximum=320, required=required)
    if value is not None and not EMAIL.fullmatch(value):
        raise ValueError("E-posta adresi geçersiz")
    return value


def _instant(value: Any = None) -> datetime:
    if value is None:
        return datetime.now(timezone.utc)
    if isinstance(value, str):
        try:
            value = datetime.fromisoformat(value.replace("Z", "+00:00"))
        except ValueError:
            raise ValueError("Tarih ISO biçiminde ve saat dilimi içermeli") from None
    if not isinstance(value, datetime) or value.utcoffset() is None:
        raise ValueError("Tarih ISO biçiminde ve saat dilimi içermeli")
    return value.astimezone(timezone.utc)


def _quantity(value: Any) -> str | None:
    if value is None or value == "":
        return None
    text = str(value).strip()
    if isinstance(value, bool) or len(text) > 32 or not re.fullmatch(r"\d+(?:[.,]\d{1,6})?", text):
        raise ValueError("Miktar sıfır veya pozitif, en çok 6 ondalıklı olmalı")
    try:
        number = Decimal(text.replace(",", "."))
    except InvalidOperation:
        raise ValueError("Miktar geçersiz") from None
    if not number.is_finite() or number > Decimal("1e12"):
        raise ValueError("Miktar sınır dışında")
    return format(number.normalize(), "f")


def _no_secrets(value: Any, depth: int = 0) -> None:
    if depth > 12:
        raise ValueError("Veri iç içe yapı sınırını aşıyor")
    if isinstance(value, dict):
        for key, item in value.items():
            if not isinstance(key, str):
                raise ValueError("JSON alan adları metin olmalı")
            if re.sub(r"[^a-z0-9]", "", key.casefold()) in SECRET_KEYS:
                raise ValueError("Bağlantı sırrı veya HTTP başlığı talep kuyruğuna yazılamaz")
            _no_secrets(item, depth + 1)
    elif isinstance(value, list):
        for item in value:
            _no_secrets(item, depth + 1)


def _json(value: Any, maximum: int = 200_000) -> str:
    _no_secrets(value)
    try:
        serialized = json.dumps(value, ensure_ascii=False, sort_keys=True, allow_nan=False)
    except (ValueError, TypeError):
        raise ValueError("Yalnız sonlu sayılar ve JSON alanları kaydedilebilir") from None
    if len(serialized.encode("utf-8")) > maximum:
        raise ValueError("Talep veya teklif boyut sınırını aşıyor")
    return serialized


def _regular_file_bytes(filename, maximum):
    """Read a bounded regular artifact without following a final symlink."""
    path = Path(filename)
    if path.is_symlink():
        raise ValueError("Taslak dosyası sembolik bağlantı olamaz")
    descriptor = os.open(path, os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0) | getattr(os, "O_NONBLOCK", 0))
    try:
        metadata = os.fstat(descriptor)
        if not stat.S_ISREG(metadata.st_mode) or not 0 < metadata.st_size <= maximum:
            raise ValueError("Taslak dosyası boş veya boyut sınırının dışında")
        with os.fdopen(descriptor, "rb", closefd=False) as handle:
            value = handle.read(maximum + 1)
        if not 0 < len(value) <= maximum:
            raise ValueError("Taslak dosyası boş veya boyut sınırının dışında")
        return value
    finally:
        os.close(descriptor)


def _unique_json_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("JSON alanları yinelenemez")
        result[key] = value
    return result


def _question_artifact_valid(row):
    """A path alone is not a prepared question; source and bytes must match."""
    keys = row.keys()
    fields = ("question_draft_text", "question_draft_sha256", "question_source_sha256")
    if not row["question_draft_path"] or any(key not in keys or not row[key] for key in fields):
        return False
    try:
        content = row["question_draft_text"].encode("utf-8")
        source_hash = hashlib.sha256(row["payload"].encode("utf-8")).hexdigest()
        return (row["question_source_sha256"] == source_hash
                and hashlib.sha256(content).hexdigest() == row["question_draft_sha256"]
                and _regular_file_bytes(row["question_draft_path"], 200_000) == content)
    except (OSError, ValueError, TypeError, AttributeError):
        return False


def _question_text(request):
    return (
        "E-POSTA TASLAĞI — GÖNDERİLMEDİ\n"
        f"Alıcı: {request['requester']}\n"
        f"Konu: {request['id']} — araştırma bitiş zamanı\n\n"
        f"{request['material_name']} için tedarikçi araştırmasını ve gelen tekliflerin karşılaştırmasını "
        "hangi tarih ve saate kadar tamamlamamı istersiniz?\n"
        "Lütfen bitiş tarihini ve saati Türkiye saati olarak belirtin. Her talebin süresi ayrı belirlenir; "
        "varsayılan süre atanmaz.\n"
        "Süre kesinleştiğinde teklif e-postaları ve varsa teknik özellikleri, vade farkı, aylık fark oranları "
        "ve KDV beyanları karşılaştırılarak yönetici raporu taslağı hazırlanacaktır.\n"
        f"Talep kimliği: {request['id']}\n"
    )


def _report_artifact_valid(filename, *, request_id=None, offer_revision=None, report_revision=None):
    """Verify new worker manifests; older manually recorded files must be nonempty."""
    if not filename:
        return False
    try:
        path = Path(filename)
        _regular_file_bytes(path, 10_000_000)
        manifest_path = path.parent / "manifest.json"
        worker_directory = re.search(r"_yonetici_raporu_v\d+_o\d+_", path.parent.name)
        if manifest_path.is_symlink():
            return False
        if not manifest_path.is_file():
            return not worker_directory
        manifest = json.loads(_regular_file_bytes(manifest_path, 64_000), object_pairs_hook=_unique_json_object)
        for key, expected in (("request_id", request_id), ("offer_revision", offer_revision),
                              ("report_revision", report_revision)):
            if expected is not None and manifest.get(key) != expected:
                return False
        files = manifest.get("files")
        if not isinstance(files, list) or not 1 <= len(files) <= 10:
            return False
        names = set()
        for item in files:
            name, digest = item["name"], item["sha256"]
            if (not isinstance(name, str) or Path(name).name != name or name in names
                    or not re.fullmatch(r"[a-f0-9]{64}", digest)):
                return False
            names.add(name)
            artifact = path.parent / name
            if hashlib.sha256(_regular_file_bytes(artifact, 10_000_000)).hexdigest() != digest:
                return False
        return path.name in names
    except (OSError, ValueError, KeyError, TypeError, AttributeError, RecursionError):
        return False


class CaseStore:
    def __init__(self, path: str | Path = DEFAULT_PATH):
        self.path = Path(path).expanduser().resolve()
        self.path.parent.mkdir(parents=True, exist_ok=True)
        with self._connect() as connection:
            connection.executescript("""
                CREATE TABLE IF NOT EXISTS requests (
                    id TEXT PRIMARY KEY, source TEXT NOT NULL, source_key TEXT NOT NULL UNIQUE,
                    payload TEXT NOT NULL, created_at TEXT NOT NULL, deadline_at TEXT,
                    question_claimed INTEGER NOT NULL DEFAULT 0, question_draft_path TEXT,
                    offer_revision INTEGER NOT NULL DEFAULT 0, report_revision INTEGER NOT NULL DEFAULT 0,
                    report_offer_revision INTEGER NOT NULL DEFAULT -1, report_path TEXT, report_at TEXT
                );
                CREATE TABLE IF NOT EXISTS offers (
                    id TEXT PRIMARY KEY, request_id TEXT NOT NULL REFERENCES requests(id),
                    message_key TEXT NOT NULL UNIQUE, payload TEXT NOT NULL, added_at TEXT NOT NULL
                );
                CREATE INDEX IF NOT EXISTS offers_request ON offers(request_id);
                CREATE INDEX IF NOT EXISTS requests_deadline ON requests(deadline_at);
            """)
            # Existing queues migrate only during a mutating Store open. Status
            # uses read-only SQL and treats legacy unverified artifacts as pending.
            connection.execute("BEGIN IMMEDIATE")
            columns = {row["name"] for row in connection.execute("PRAGMA table_info(requests)")}
            for name in ("question_draft_text", "question_draft_sha256", "question_source_sha256"):
                if name not in columns:
                    connection.execute(f"ALTER TABLE requests ADD COLUMN {name} TEXT")

    @contextmanager
    def _connect(self):
        connection = sqlite3.connect(self.path, timeout=10)
        connection.row_factory = sqlite3.Row
        try:
            connection.execute("PRAGMA foreign_keys=ON")
            connection.execute("PRAGMA busy_timeout=10000")
            with connection:
                yield connection
        finally:
            connection.close()

    @staticmethod
    def _request_row(connection: sqlite3.Connection, request_id: str) -> sqlite3.Row:
        row = connection.execute("SELECT * FROM requests WHERE id=?", (request_id,)).fetchone()
        if row is None:
            raise ValueError("Talep bulunamadı")
        return row

    def _snapshot(self, connection: sqlite3.Connection, row: sqlite3.Row, now: datetime) -> dict:
        request = json.loads(row["payload"])
        request["id"] = row["id"]
        request["deadline_at"] = row["deadline_at"]
        if row["deadline_at"] is None:
            state = "awaiting_deadline"
        elif now < _instant(row["deadline_at"]):
            state = "collecting"
        elif (row["report_offer_revision"] == row["offer_revision"]
              and _report_artifact_valid(row["report_path"], request_id=row["id"],
                                         offer_revision=row["offer_revision"], report_revision=row["report_revision"])):
            state = "report_prepared"
        else:
            state = "ready_for_report"
        request["state"] = state
        request["report_revision"] = row["report_revision"]
        request["offer_revision"] = row["offer_revision"]
        offers = [json.loads(item["payload"]) for item in connection.execute(
            "SELECT payload FROM offers WHERE request_id=? ORDER BY added_at,id", (row["id"],)
        )]
        question_status = "draft_preparing" if row["question_claimed"] else "pending"
        if row["question_draft_path"]:
            question_status = "draft_prepared" if _question_artifact_valid(row) else "artifact_missing_or_changed"
        return {
            "request": request, "offers": offers, "as_of": now.isoformat(),
            "source": row["source"], "report_path": row["report_path"], "report_at": row["report_at"],
            "question_draft": {
                "status": question_status,
                "path": row["question_draft_path"], "recipient": request["requester"], "sent": False,
            },
        }

    def upsert_request(self, request: dict, source: str) -> dict:
        """Register immutable intake facts; deadline replies use set_deadline()."""
        if not isinstance(request, dict):
            raise ValueError("Talep JSON nesnesi olmalı")
        _no_secrets(request)
        if not isinstance(source, str):
            raise ValueError("Talep kaynağı metin olmalı")
        source = {"sap_api": "sap", "mail": "mail_request"}.get(source, source)
        if source not in {"sap", "mail_request", "manual"}:
            raise ValueError("Talep kaynağı sap, mail_request veya manual olmalı")
        material_name = _text(request.get("material_name") or request.get("name"), maximum=300, required=True)
        supplied_id = _text(request.get("id") or request.get("request_id"), maximum=200)
        requester = _email(request.get("requester") or request.get("sender"), required=source in {"mail_request", "manual"})
        mailbox = _email(request.get("mailbox"))
        message_id = _text(request.get("message_id"), maximum=500, required=source == "mail_request")
        if source in {"sap", "manual"}:
            if supplied_id is None:
                raise ValueError("Talep kimliği açıkça sağlanmalı")
            identity = source + ":" + supplied_id
            request_id = supplied_id
        else:
            identity = "mail_request:" + _json([mailbox or "", message_id])
            request_id = supplied_id or "MAIL-" + hashlib.sha256(identity.encode()).hexdigest()[:20]
        specs = request.get("required_specs") or {}
        if not isinstance(specs, dict) or len(specs) > 30:
            raise ValueError("Teknik şartname en çok 30 alanlı nesne olmalı")
        unit = _text(request.get("unit"), maximum=32)
        payload = {
            "material_code": _text(request.get("material_code"), maximum=100),
            "material_name": material_name, "quantity": _quantity(request.get("quantity")),
            "unit": unit, "required_specs": specs, "requester": requester,
            "mailbox": mailbox, "message_id": message_id,
        }
        if "sap_requisition" in request:
            metadata = request["sap_requisition"]
            fields = {"source_system", "purchase_requisition", "purchase_requisition_item"}
            if source != "sap" or not isinstance(metadata, dict) or set(metadata) != fields:
                raise ValueError("SAP talep kaynağı yalnız sap için üç açık kimlik alanıyla belirtilmeli")
            canonical_metadata = {key: _text(metadata[key], maximum=100, required=True) for key in sorted(fields)}
            if any(any(ord(char) < 32 or ord(char) == 127 for char in value) for value in canonical_metadata.values()):
                raise ValueError("SAP talep kimlik alanları tek satırlı metin olmalı")
            payload["sap_requisition"] = canonical_metadata
        # Keep optional purchasing scope immutable without changing old records.
        for key in ("delivery_place", "need_by", "material_kind"):
            if request.get(key) not in (None, ""):
                payload[key] = _text(request[key], maximum=500, required=True)
        if payload.get("material_kind") not in (None, "hammadde", "sarf"):
            raise ValueError("Malzeme türü hammadde veya sarf olmalı")
        serialized = _json(payload)
        now = _instant()
        with self._connect() as connection:
            connection.execute("BEGIN IMMEDIATE")
            existing = connection.execute("SELECT * FROM requests WHERE source_key=?", (identity,)).fetchone()
            if existing is not None:
                if existing["id"] != request_id or existing["payload"] != serialized:
                    raise ValueError("Aynı kaynak talep kimliği farklı malzeme veya içerikle yeniden kullanılamaz")
                return self._snapshot(connection, existing, now)
            if connection.execute("SELECT 1 FROM requests WHERE id=?", (request_id,)).fetchone():
                raise ValueError("Talep kimliği başka kaynağa ait; eşleşme belirsiz")
            connection.execute(
                "INSERT INTO requests(id,source,source_key,payload,created_at) VALUES(?,?,?,?,?)",
                (request_id, source, identity, serialized, now.isoformat()),
            )
            return self._snapshot(connection, self._request_row(connection, request_id), now)

    def set_deadline(self, request_id: str, deadline_at: str, requester_email: str, now=None) -> dict:
        now = _instant(now)
        if not deadline_at:
            raise ValueError("Bitiş zamanı talep sahibinin yanıtında açıkça belirtilmeli")
        deadline = _instant(deadline_at)
        owner = _email(requester_email, required=True)
        with self._connect() as connection:
            connection.execute("BEGIN IMMEDIATE")
            row = self._request_row(connection, request_id)
            request = json.loads(row["payload"])
            if request["requester"] is None or owner != request["requester"]:
                raise ValueError("Bitiş zamanını yalnız talebin kayıtlı sahibi belirleyebilir")
            if row["deadline_at"] and deadline == _instant(row["deadline_at"]):
                return self._snapshot(connection, row, now)
            if deadline <= now:
                raise ValueError("Yeni bitiş zamanı gelecekte olmalı")
            if row["deadline_at"] and (now >= _instant(row["deadline_at"]) or row["report_revision"]):
                raise ValueError("Tamamlanan araştırmanın bitiş zamanı değiştirilemez; yeni talep açılmalı")
            connection.execute("UPDATE requests SET deadline_at=? WHERE id=?", (deadline.isoformat(), request_id))
            return self._snapshot(connection, self._request_row(connection, request_id), now)

    def append_offer(self, request_id: str, offer: dict) -> dict:
        if not isinstance(offer, dict):
            raise ValueError("Teklif JSON nesnesi olmalı")
        _no_secrets(offer)
        if offer.get("request_id") != request_id:
            raise ValueError("Teklif talep kimliğine açıkça bağlanmalı")
        canonical = {key: value for key, value in offer.items() if key in OFFER_FIELDS}
        email = canonical.get("email")
        if not isinstance(email, dict):
            raise ValueError("Teklifin kaynak e-postası gerekli")
        email = {key: value for key, value in email.items() if key in EMAIL_FIELDS}
        canonical["email"] = email
        message_id = _text(email.get("message_id"), maximum=500, required=True)
        mailbox = _email(email.get("mailbox"))
        _email(email.get("sender"), required=True)
        _instant(email.get("received_at")) if email.get("received_at") else None
        if not email.get("received_at"):
            raise ValueError("Teklif e-postasının saat dilimli geliş tarihi gerekli")
        attachments = email.get("attachments", [])
        if not isinstance(attachments, list) or len(attachments) > 30:
            raise ValueError("E-posta ekleri en çok 30 kayıtlı liste olmalı")
        if any(not isinstance(item, dict) for item in attachments):
            raise ValueError("E-posta eki JSON nesnesi olmalı")
        email["attachments"] = [{key: value for key, value in item.items() if key in ATTACHMENT_FIELDS} for item in attachments]
        offer_id = _text(offer.get("id"), maximum=200) or "OFFER-" + hashlib.sha256(_json([mailbox, message_id]).encode()).hexdigest()[:20]
        canonical["id"] = offer_id
        _text(canonical.get("supplier"), maximum=500, required=True)
        serialized = _json(canonical, maximum=500_000)
        now = _instant()
        with self._connect() as connection:
            connection.execute("BEGIN IMMEDIATE")
            row = self._request_row(connection, request_id)
            request = json.loads(row["payload"])
            original_code = request["material_code"]
            if original_code:
                if _text(offer.get("material_code"), maximum=100) != original_code:
                    raise ValueError("Teklif malzeme kodu özgün taleple eşleşmiyor")
            elif _text(offer.get("material_name"), maximum=300) != request["material_name"]:
                raise ValueError("Kod yoksa teklif özgün malzeme adıyla açıkça eşleşmeli")
            # Missing mailbox uses the known original mailbox, never a guessed address.
            identity = _json([mailbox or request["mailbox"] or "", message_id])
            existing = connection.execute("SELECT * FROM offers WHERE message_key=? OR id=?", (identity, offer_id)).fetchall()
            if existing:
                if (len(existing) != 1 or existing[0]["request_id"] != request_id
                        or existing[0]["message_key"] != identity or existing[0]["payload"] != serialized):
                    raise ValueError("Aynı teklif e-postası farklı talep veya içerikle eşleştirilemez")
                return self._snapshot(connection, row, now)
            has_rfq_table = connection.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' AND name='rfq_drafts'"
            ).fetchone()
            if has_rfq_table and connection.execute(
                "SELECT 1 FROM rfq_drafts WHERE request_id=? LIMIT 1", (request_id,)
            ).fetchone():
                raise ValueError("Bu talebin teklif isteği kaydı var; yeni yanıtı rfq_worker.py ingest-response ile kaynak konuşmasına bağlayın")
            connection.execute(
                "INSERT INTO offers(id,request_id,message_key,payload,added_at) VALUES(?,?,?,?,?)",
                (offer_id, request_id, identity, serialized, now.isoformat()),
            )
            connection.execute("UPDATE requests SET offer_revision=offer_revision+1 WHERE id=?", (request_id,))
            return self._snapshot(connection, self._request_row(connection, request_id), now)

    def snapshot(self, request_id: str, now=None) -> dict:
        now = _instant(now)
        with self._connect() as connection:
            return self._snapshot(connection, self._request_row(connection, request_id), now)

    def list_due(self, now=None) -> list[dict]:
        now = _instant(now)
        with self._connect() as connection:
            rows = connection.execute("SELECT * FROM requests WHERE deadline_at IS NOT NULL ORDER BY deadline_at,id").fetchall()
            snapshots = [self._snapshot(connection, row, now) for row in rows]
            return [item for item in snapshots if item["request"]["state"] == "ready_for_report"]

    def claim_pending_questions(self) -> list[dict]:
        """Claim question *drafts* once; no sent/delivered state is invented."""
        now = _instant()
        with self._connect() as connection:
            connection.execute("BEGIN IMMEDIATE")
            rows = connection.execute(
                "SELECT * FROM requests WHERE deadline_at IS NULL AND question_claimed=0 ORDER BY created_at,id"
            ).fetchall()
            output = []
            for row in rows:
                if json.loads(row["payload"])["requester"] is None:
                    continue
                connection.execute("UPDATE requests SET question_claimed=1 WHERE id=?", (row["id"],))
                output.append(self._snapshot(connection, self._request_row(connection, row["id"]), now))
            return output

    def set_question_draft(self, request_id: str, path: str | Path) -> dict:
        path = Path(path).expanduser().absolute()
        path = path.parent.resolve() / path.name
        try:
            content = _regular_file_bytes(path, 200_000).decode("utf-8")
        except (OSError, ValueError, UnicodeError):
            raise ValueError("Süre sorusu taslağı önce dosyaya kaydedilmeli")
        now = _instant()
        with self._connect() as connection:
            connection.execute("BEGIN IMMEDIATE")
            row = self._request_row(connection, request_id)
            if row["deadline_at"] is not None:
                raise ValueError("Bitiş zamanı biliniyor; yeni süre sorusu hazırlanmamalı")
            if json.loads(row["payload"])["requester"] is None:
                raise ValueError("Taslak alıcısı bilinmiyor")
            if (_question_artifact_valid(row) and row["question_draft_path"] != str(path)):
                raise ValueError("Bu talep için süre sorusu taslağı zaten hazırlanmış")
            if row["question_draft_text"] and row["question_draft_text"] != content:
                raise ValueError("Kaydedilmiş süre sorusunun içeriği değiştirilemez")
            connection.execute("""UPDATE requests SET question_claimed=1,question_draft_path=?,
                question_draft_text=?,question_draft_sha256=?,question_source_sha256=? WHERE id=?""",
                (str(path), content, hashlib.sha256(content.encode()).hexdigest(),
                 hashlib.sha256(row["payload"].encode()).hexdigest(), request_id))
            return self._snapshot(connection, self._request_row(connection, request_id), now)

    def prepare_question_drafts(self, output_dir: str | Path) -> list[dict]:
        """Publish/recover one immutable artifact per pending request under lock.

        A process interrupted after claiming or after file creation is recoverable:
        durable DB text is authoritative and uncommitted artifact paths are never
        reported ready. No claim lease is needed because this bounded local write
        holds the SQLite transaction until the selected path and hashes commit.
        """
        now = _instant()
        output = Path(output_dir).expanduser().resolve()
        drafts = []
        with self._connect() as connection:
            connection.execute("BEGIN IMMEDIATE")
            rows = connection.execute("SELECT * FROM requests WHERE deadline_at IS NULL ORDER BY created_at,id").fetchall()
            for row in rows:
                request = {**json.loads(row["payload"]), "id": row["id"]}
                if not request["requester"] or _question_artifact_valid(row):
                    continue
                source_hash = hashlib.sha256(row["payload"].encode()).hexdigest()
                content = row["question_draft_text"]
                if (not isinstance(content, str) or not content or len(content.encode()) > 200_000
                        or row["question_source_sha256"] != source_hash
                        or hashlib.sha256(content.encode()).hexdigest() != row["question_draft_sha256"]):
                    content = _question_text(request)
                output.mkdir(parents=True, exist_ok=True)
                prefix = "talep_" + hashlib.sha256(row["id"].encode()).hexdigest()[:20] + "_sure_sorusu_"
                directory = Path(tempfile.mkdtemp(prefix=prefix, dir=output))
                path = directory / "sure_sorusu.txt"
                with path.open("x", encoding="utf-8") as handle:
                    handle.write(content)
                path.chmod(0o600)
                digest = hashlib.sha256(content.encode()).hexdigest()
                if hashlib.sha256(_regular_file_bytes(path, 200_000)).hexdigest() != digest:
                    raise ValueError("Süre sorusu dosya özeti doğrulanamadı")
                connection.execute("""UPDATE requests SET question_claimed=1,question_draft_path=?,
                    question_draft_text=?,question_draft_sha256=?,question_source_sha256=? WHERE id=?""",
                    (str(path), content, digest, source_hash, row["id"]))
                drafts.append(self._snapshot(connection, self._request_row(connection, row["id"]), now))
        return drafts

    def mark_report_prepared(self, request_id: str, artifact_path: str | Path, now=None,
                             *, expected_offer_revision: int | None = None) -> dict:
        now = _instant(now)
        path = Path(artifact_path).expanduser().absolute()
        path = path.parent.resolve() / path.name
        if not _report_artifact_valid(path):
            raise ValueError("Yönetici raporu önce boş olmayan dosyaya kaydedilmeli")
        with self._connect() as connection:
            connection.execute("BEGIN IMMEDIATE")
            row = self._request_row(connection, request_id)
            if row["deadline_at"] is None or now < _instant(row["deadline_at"]):
                raise ValueError("Araştırma süresi dolmadan rapor tamamlandı sayılamaz")
            if expected_offer_revision is not None and row["offer_revision"] != expected_offer_revision:
                raise ValueError("Rapor hazırlanırken yeni teklif geldi; rapor yenilenmeli")
            if (row["report_offer_revision"] == row["offer_revision"]
                    and _report_artifact_valid(row["report_path"], request_id=row["id"],
                                               offer_revision=row["offer_revision"], report_revision=row["report_revision"])):
                if row["report_path"] != str(path):
                    raise ValueError("Bu teklif revizyonu için rapor zaten hazırlandı")
                return self._snapshot(connection, row, now)
            if not _report_artifact_valid(path, request_id=request_id, offer_revision=row["offer_revision"],
                                          report_revision=row["report_revision"] + 1):
                raise ValueError("Yönetici raporu dosya özeti, talep veya revizyon bilgisi doğrulanamadı")
            connection.execute(
                "UPDATE requests SET report_revision=report_revision+1,report_offer_revision=offer_revision,report_path=?,report_at=? WHERE id=?",
                (str(path), now.isoformat(), request_id),
            )
            return self._snapshot(connection, self._request_row(connection, request_id), now)


"""İki girişi talep, süre ve stok kapsamına bağlar; beklerken model dalını durdurur."""

import csv
import hashlib
import io
import json
from datetime import datetime
from pathlib import Path
from zoneinfo import ZoneInfo

from lfx.custom import Component
from lfx.io import DropdownInput, MessageTextInput, Output
from lfx.schema.message import Message

INTAKE_MARKER = "TALEP GİRİŞİ (JSON)\n"
CASE_MARKER = "TEKLİF DOSYASI (JSON)\n"


def _ctx_parse(value):
    text = value.text if isinstance(value, Message) else str(value or "")
    if not text.strip():
        return {}
    if INTAKE_MARKER in text:
        text = text.rsplit(INTAKE_MARKER, 1)[1]
    payload = json.loads(text)
    if not isinstance(payload, dict):
        raise ValueError("Talep bağlamı nesne olmalı")
    return payload


def coordinate_request(context, selected_code="", store=None):
    """SAP kalemlerini ayrı dosyalara bağlar; süre yalnız kayıtlı sahibinden gelir."""
    result = {"ready": False, "context": context, "case": None, "cases": [],
              "reason": "Giriş bağlantısı veya talep bekleniyor."}
    if not isinstance(context, dict):
        return result
    deadline_errors = {
        "Bitiş tarihi saat dilimiyle birlikte gelecekte olmalı",
        "Bitiş tarihini saat dilimiyle birlikte gelecekte bir zaman olarak belirtin",
    }
    errors = context.get("errors") or []
    deadline_only_invalid = (context.get("status") == "invalid" and isinstance(errors, list)
                             and bool(errors) and all(error in deadline_errors for error in errors))
    if context.get("status") != "ready" and not deadline_only_invalid:
        details = context.get("errors") or context.get("warnings") or [result["reason"]]
        result["reason"] = "\n".join(str(value) for value in details)
        return result
    materials = context.get("materials", [])
    if not isinstance(materials, list) or not materials:
        result["reason"] = "Araştırılacak malzeme bilgisi yok."
        return result
    if any(not isinstance(item, dict) for item in materials):
        result["reason"] = "Malzeme listesi nesne satırları içermeli."
        return result
    is_sap = context.get("source") == "sap_api"
    is_requisition = is_sap and context.get("data_kind") == "purchase_requisitions"
    if is_sap and selected_code:
        materials = [item for item in materials if item.get("material_code") == selected_code.strip()]
    if not materials or any(not isinstance(item, dict) or not isinstance(item.get("name"), str)
                            or not item["name"].strip() for item in materials):
        result["reason"] = "Seçilen kod bulunamadı veya malzeme bilgisi eksik."
        return result
    if (is_sap and len(materials) > 10) or (not is_sap and len(materials) != 1):
        result["reason"] = ("SAP araştırması en çok 10 kalem içerebilir; daha küçük kapsam seçin. Hiçbir kalem kırpılmadı."
                            if is_sap else "E-posta özel talebi tek malzeme içermeli.")
        return result
    materials = [dict(item) for item in materials]
    for item in materials:
        item["material_code"] = item.get("material_code") or "M_" + hashlib.sha256(item["name"].casefold().encode()).hexdigest()[:10]
    if len({item["material_code"] for item in materials}) != len(materials):
        result["reason"] = "Aynı SAP malzeme kodu birden çok satırda var; birleştirme veya açık seçim gerekli."
        return result
    request = dict(context.get("request") or {})
    context = {**context, "materials": materials, "request": request}
    result["context"] = context
    if is_requisition and (len(materials) != 1 or not isinstance(request.get("sap_requisition"), dict)
                           or set(request["sap_requisition"]) != {"source_system", "purchase_requisition", "purchase_requisition_item"}):
        result["reason"] = "Tek bir SAP satın alma talep kalemi ve kaynak kimliği seçilmeli."
        return result
    if not request.get("requester"):
        result["reason"] = "Talep sahibi belirlenmeli; araştırma bitiş süresi ilgili kişiden sorulacak."
        return result
    if context.get("source") == "mail_request" and not request.get("message_id"):
        result["reason"] = "Kaynak e-posta kimliği gerekli. Bot kutusu bağlanana kadar bu giriş yalnız yerel ön hazırlıktır."
        return result
    if store is None:
        store = CaseStore(Path.cwd() / ".codex/agents/satin-alma-stok/cases/requests.db")
    cases = []
    requests = []
    for item in materials:
        item_request = {**request, "material_code": item["material_code"], "material_name": item["name"],
                        "quantity": item.get("quantity"), "unit": item.get("unit"),
                        "required_specs": item.get("required_specs") or request.get("required_specs") or {}}
        if is_sap:
            if not request.get("id"):
                result["reason"] = "SAP talep kimliği eksik; kalemler kayıt altına alınamadı."
                return result
            # A PR's identity is its source system + requisition + item, not
            # the current material code or contents of the returned page.
            item_request["id"] = str(request["id"]) if is_requisition else str(request["id"]) + "-" + item["material_code"]
        requests.append(item_request)
    if deadline_only_invalid:
        # Invalid dates never open new cases. Every case must already have an
        # owner-confirmed deadline. upsert below verifies immutable source facts.
        try:
            for item_request in requests:
                snapshot = store.snapshot(item_request.get("id"))
                if not snapshot["request"].get("deadline_at"):
                    raise ValueError("Kaydedilmiş süre yok")
        except (ValueError, TypeError):
            result["reason"] = "Bitiş zamanı geçersiz ve devam edilebilecek onaylı talep bulunamadı."
            return result
    for item_request in requests:
        case = store.upsert_request(item_request, context.get("source"))
        if item_request.get("deadline_at") and not deadline_only_invalid:
            case = store.set_deadline(case["request"]["id"], item_request["deadline_at"], item_request["requester"])
        cases.append(case)
    result["cases"] = cases
    result["case"] = cases[0]
    if len(cases) == 1:
        context["request"] = cases[0]["request"]
    else:
        states = {case["request"]["state"] for case in cases}
        dates = {case["request"]["deadline_at"] for case in cases}
        common_state = ("awaiting_deadline" if "awaiting_deadline" in states else
                        "collecting" if "collecting" in states else
                        "ready_for_report" if "ready_for_report" in states else "report_prepared")
        context["request"] = {**request, "state": common_state,
                              "deadline_at": next(iter(dates)) if len(dates) == 1 else None}
        context["request_ids"] = [case["request"]["id"] for case in cases]
    if deadline_only_invalid:
        context["status"] = "ready"
        context["errors"] = []
        context["warnings"] = [*(context.get("warnings") or []),
                               "Yeni/geçersiz süre kullanılmadı; kayıtlı talep sahibinin onaylı süresiyle devam edildi."]
    if any(case["request"]["state"] == "awaiting_deadline" for case in cases):
        result["reason"] = (f"Talep {request.get('id') or cases[0]['request']['id']}: "
                            f"{', '.join(item['name'] for item in materials)} araştırmasını hangi tarih ve saate kadar "
                            "tamamlamamı istersiniz? Türkiye saatini belirtin. Süre sorusu taslaktır; gönderilmedi.")
        return result
    result["ready"] = True
    result["reason"] = "Araştırma ve teklif takibi için süre kaydedildi."
    return result


def stock_table_from_context(context):
    buffer = io.StringIO()
    # Bağlam başlıktan önce tutulur; JSON tablonun veri satırı sayılmaz.
    buffer.write(INTAKE_MARKER + json.dumps(context, ensure_ascii=False, allow_nan=False) + "\n\n")
    buffer.write("Rapor tarihi: " + datetime.now(ZoneInfo("Europe/Istanbul")).date().isoformat() + "\n")
    writer = csv.writer(buffer, delimiter=";", lineterminator="\n")
    writer.writerow(["malzeme_kodu", "tanım", "birim", "mevcut_stok", "ayrılmış_stok", "kesin_açık_sipariş",
                     "günlük_tüketim", "termin_gün", "emniyet_stok", "açık_sipariş_teslim_tarihi"])
    for item in context.get("materials", []):
        values = [item.get(key) for key in ["material_code", "name", "unit", "stock", "reserved_stock",
                                          "open_order_quantity", "daily_consumption", "lead_time_days",
                                          "safety_stock", "open_order_delivery_date"]]
        writer.writerow(["" if value is None else str(value).replace("\n", " ").replace("\r", " ") for value in values])
    return buffer.getvalue()


class ProcurementRequestCoordinator(Component):
    display_name = "Talep ve Süre Takibi"
    description = "Malzeme talebi, e-posta veya isteğe bağlı SAP girişini seçer; kişiye özel süreyi takip eder."
    name = "ProcurementRequestCoordinator"
    icon = "GitBranch"
    inputs = [
        MessageTextInput(name="manual_context", display_name="Malzeme talebi", required=False, value=""),
        MessageTextInput(name="sap_context", display_name="SAP girişi", required=False, value=""),
        MessageTextInput(name="mail_context", display_name="E-posta talebi", required=False, value=""),
        DropdownInput(name="input_source", display_name="Talep kaynağı", options=["Malzeme talebi", "E-posta özel talep", "SAP API"], value="Malzeme talebi"),
        MessageTextInput(name="selected_material_code", display_name="SAP listesinden malzeme kodu", value="",
                         info="Boşsa SAP'den gelen tüm kalemler araştırılır (en çok10); belirli kodla kapsam daraltılır."),
    ]
    outputs = [
        Output(name="stock_table", display_name="Süreli araştırma girdisi", method="build_stock_table", group_outputs=True),
        Output(name="request_context", display_name="Talep ve süre bağlamı", method="build_request_context", group_outputs=True),
        Output(name="case_data", display_name="Teklif dosyası", method="build_case_data", group_outputs=True),
        Output(name="pending_response", display_name="Süre / bağlantı bekleniyor", method="build_pending", group_outputs=True),
    ]

    def _prepare(self):
        if not hasattr(self, "_prepared_intake"):
            selected = (self.sap_context if self.input_source == "SAP API" else
                        self.manual_context if self.input_source == "Malzeme talebi" else self.mail_context)
            try:
                self._prepared_intake = coordinate_request(_ctx_parse(selected), self.selected_material_code)
            except (ValueError, TypeError, KeyError):
                self._prepared_intake = {"ready": False, "context": {}, "case": None,
                                        "reason": "Talep/süre kaydı doğrulanamadı; kaynak alanlarını kontrol edin."}
            self.status = self._prepared_intake["reason"]
        return self._prepared_intake

    def _guard(self, prepared):
        if getattr(self, "_vertex", None) is not None:
            excluded = ["pending_response"] if prepared["ready"] else ["stock_table", "case_data"]
            for output in excluded:
                self.stop(output)
            # One replacement keeps both pending exclusions under the same
            # source key; separate calls would restore the first excluded path.
            self.graph.exclude_branches_conditionally(self._id, excluded)

    def build_stock_table(self) -> Message:
        prepared = self._prepare()
        self._guard(prepared)
        return Message(text=stock_table_from_context(prepared["context"]) if prepared["ready"] else "")

    def build_request_context(self) -> Message:
        prepared = self._prepare()
        self._guard(prepared)
        return Message(text=INTAKE_MARKER + json.dumps(prepared["context"], ensure_ascii=False))

    def build_case_data(self) -> Message:
        prepared = self._prepare()
        self._guard(prepared)
        cases = prepared.get("cases") or []
        case = ({"cases": cases} if len(cases) > 1 else prepared["case"]) or {"request": {"state": "awaiting_configuration"}, "offers": [],
                                     "as_of": datetime.now(ZoneInfo("Europe/Istanbul")).isoformat()}
        return Message(text=CASE_MARKER + json.dumps(case, ensure_ascii=False))

    def build_pending(self) -> Message:
        prepared = self._prepare()
        self._guard(prepared)
        return Message(text="" if prepared["ready"] else prepared["reason"])

"""Kaynak e-posta/ek alıntılarıyla doğrulanan, yerel teklif karşılaştırması.

KDV hesabı tedarikçinin açık beyanını kıyaslar; vergi uygulamasının hukuki
uygunluğunu doğrulamaz. Eksik veriler için oran, süre veya fiyat varsayılmaz.
"""

import ipaddress
import json
import re
import unicodedata
from datetime import datetime, timezone
from decimal import Decimal, DecimalException, InvalidOperation, localcontext
from urllib.parse import quote, urlsplit, urlunsplit
from zoneinfo import ZoneInfo

from lfx.custom import Component
from lfx.io import MessageTextInput, Output
from lfx.schema.message import Message

MARKER = "TEKLİF DOSYASI (JSON)\n"
RESULT_MARKER = "TEKLİF KARŞILAŞTIRMASI (JSON)\n"
NUMERIC_FIELDS = {"quantity", "cash_unit_price", "term_unit_price", "term_days", "vat_rate_pct", "delivery_days"}
PRICE_BASES = {"vat_exclusive", "vat_inclusive", "not_stated"}
VAT_BASES = {"including_term_markup", "principal_only", "not_stated"}
FINAL_STATES = {"completed", "final", "ready_for_report", "report_prepared"}


def _text(value, limit=500_000):
    value = value.text if isinstance(value, Message) else value
    if not isinstance(value, str) or len(value) > limit:
        raise ValueError("Teklif dosyası metin olmalı ve boyut sınırını aşmamalıdır.")
    return value


def _bounded(value, limit=500):
    return value.strip() if isinstance(value, str) and 0 < len(value.strip()) <= limit else None


def _decimal(value):
    if isinstance(value, bool) or value is None or isinstance(value, (dict, list)):
        return None
    try:
        text = str(value).strip()
        if len(text) > 80:
            return None
        number = Decimal(text.replace(",", ".") if "." not in text else text)
        return number if number.is_finite() and abs(number) <= Decimal("1e18") else None
    except InvalidOperation:
        return None


def _instant(value):
    if not isinstance(value, str) or len(value) > 80:
        return None
    try:
        instant = datetime.fromisoformat(value.replace("Z", "+00:00"))
        return instant.astimezone(timezone.utc) if instant.tzinfo is not None else None
    except ValueError:
        return None


def _display_instant(value):
    instant = _instant(value)
    return instant.astimezone(ZoneInfo("Europe/Istanbul")).strftime("%d.%m.%Y %H:%M (Europe/Istanbul)") if instant else "—"


def _public_url(value):
    if not isinstance(value, str) or len(value) > 2000 or any(char.isspace() for char in value):
        return None
    try:
        parsed = urlsplit(value)
        host = parsed.hostname
        if parsed.scheme not in {"http", "https"} or not host or parsed.username or parsed.password:
            return None
        if parsed.port is not None and parsed.port not in {80, 443}:
            return None
        try:
            if not ipaddress.ip_address(host).is_global:
                return None
        except ValueError:
            if "." not in host or host.lower().endswith((".local", ".localhost", ".internal", ".invalid", ".test")):
                return None
        return urlunsplit((parsed.scheme, parsed.netloc, quote(parsed.path, safe="/%:@-._~"),
                           quote(parsed.query, safe="=&%:@/?-._~"), quote(parsed.fragment, safe="%-._~")))
    except (ValueError, UnicodeError):
        return None


def _escape(value):
    text = "—" if value is None else str(value)
    text = " ".join(text.split())
    for char in "\\`*_{}[]()<>|~":
        text = text.replace(char, "\\" + char)
    return text


def _format(value, percent=False):
    number = _decimal(value)
    if number is None:
        return "—"
    return f"{number:.2f}" + ("%" if percent else "")


def _number_in_quote(number, quotation):
    # 1.000,50 / 1,000.50 ve sade ondalık yazımlar desteklenir; yuvarlama yapılmaz.
    for token in re.findall(r"(?<![\w])[-+]?\d[\d.,]*(?![\w])", quotation):
        if re.fullmatch(r"\d{1,3}[.,]\d{3}", token):
            # 1.000 / 1,000 hem ondalık hem binlik ayracı olabilir; yerel ayar varsayılmaz.
            continue
        variants = [token]
        if "," in token and "." in token:
            variants.append(token.replace(".", "").replace(",", ".") if token.rfind(",") > token.rfind(".")
                            else token.replace(",", ""))
        elif token.count(".") > 1 or token.count(",") > 1:
            variants.append(token.replace(".", "").replace(",", ""))
        if any(_decimal(candidate) == number for candidate in variants):
            return True
    return False


def _semantic_text(value):
    # Turkish/ASCII supplier quotations share the same small field vocabulary.
    text = unicodedata.normalize("NFKD", value.casefold().replace("ı", "i"))
    return "".join(char for char in text if not unicodedata.combining(char))


_NUMERIC_LABELS = {
    "cash_unit_price": r"cash_unit_price|(?:pesin|nakit)(?:\s+(?:birim(?:\s+fiyati?)?|fiyati?))?|cash(?:\s+(?:unit\s+price|price))?",
    "term_unit_price": r"term_unit_price|(?:vadeli|veresiye)(?:\s+(?:birim(?:\s+fiyati?)?|fiyati?))?|(?:term|credit|deferred)\s+(?:unit\s+price|price)",
    "purchase_unit_price": r"purchase_unit_price|(?:alis|satin\s+alma)\s+birim\s+fiyati?|purchase\s+unit\s+price",
    "quantity": r"quantity|qty|miktari?|adet\s+sayisi",
    "term_days": r"term_days|vade(?:\s+(?:suresi|gunu|gun))?|odeme\s+(?:suresi|vadesi)|payment\s+terms?|term(?:\s+days)?|net",
    "vat_rate_pct": r"vat_rate_pct|(?:kdv|vat)(?:\s+(?:orani|rate))?",
    "delivery_days": r"delivery_days|teslim(?:at)?(?:\s+suresi)?|termin(?:\s+suresi)?|delivery(?:\s+(?:time|days))?|lead\s+time",
}
_NUMERIC_LABEL_PATTERN = re.compile(
    r"(?<![a-z0-9_])(?:" + "|".join(f"(?P<{key}>{pattern})" for key, pattern in _NUMERIC_LABELS.items()) + r")(?![a-z_])"
)
_QUOTED_NUMBER_PATTERN = r"[-+]?\d+(?:[.,]\d+)*"
_MONEY_UNIT_PATTERN = r"(?:(?:try|tl|usd|eur|gbp)\b|[₺$€])"
_DAY_UNIT_PATTERN = r"(?:is\s+)?(?:gun|days?|d)\b"
_NUMERIC_VALUE_PATTERN = re.compile(
    r"\s*[:=]?\s*(?P<currency>" + _MONEY_UNIT_PATTERN + r"\s*)?(?P<percent>%\s*)?"
    r"(?P<number>" + _QUOTED_NUMBER_PATTERN + r")(?!\d|[.,]\d)"
)


def _numeric_field_in_quote(field, number, quotation):
    """Bind a value to its own explicit label, never to any number in a paragraph.

    One quotation may contain several distinctly labelled fields. Multiple values
    for the same field (ranges, old/new prices, alternatives) remain ambiguous;
    callers must provide a narrower, exact source quotation or request review.
    """
    text = _semantic_text(quotation)
    labels = list(_NUMERIC_LABEL_PATTERN.finditer(text))
    candidates = []
    for index, label in enumerate(labels):
        if label.lastgroup != field:
            continue
        end = labels[index + 1].start() if index + 1 < len(labels) else len(text)
        segment = text[label.end():end]
        match = _NUMERIC_VALUE_PATTERN.match(segment)
        if match is None:
            continue
        # A second number in the same label's span cannot be silently selected.
        if len(re.findall(_QUOTED_NUMBER_PATTERN, segment)) != 1:
            return False
        suffix = segment[match.end():]
        percent = bool(match.group("percent") or re.match(r"\s*%", suffix))
        monetary = bool(match.group("currency") or re.match(r"\s*" + _MONEY_UNIT_PATTERN, suffix))
        days = bool(re.match(r"\s*" + _DAY_UNIT_PATTERN, suffix))
        physical_unit = bool(re.match(r"\s*(?:kg|kilogram|g|gr|ton|adet|pcs|lt|l|m2|m3|metre)\b", suffix))
        if field.endswith("unit_price"):
            explicit_price = re.search(r"birim|unit[_\s]+price", label.group())
            per_unit = re.match(r"\s*(?:" + _MONEY_UNIT_PATTERN + r")?\s*/\s*[a-z]\w*", suffix)
            if percent or days or physical_unit or not (explicit_price or per_unit):
                continue
        if field == "quantity" and (percent or monetary or days):
            continue
        if field in {"term_days", "delivery_days"}:
            day_label = label.group().endswith(("_days", " days", " gun", " gunu"))
            if percent or monetary or physical_unit or (not day_label and not days):
                continue
        if field == "vat_rate_pct":
            percent_label = label.group().endswith(("_pct", " orani", " rate"))
            if monetary or days or physical_unit or not (percent_label or percent):
                continue
        candidates.append(match.group("number"))
    return len(candidates) == 1 and _number_in_quote(number, candidates[0])


def _evidence(offer, field, value, *, numeric_field=None):
    """Alıntı kimliği yanında gerçek kaynak içeriği ve sayısal değeri de denetlenir."""
    email = offer.get("email")
    fields = offer.get("source_fields")
    evidence = fields.get(field) if isinstance(fields, dict) else None
    if not isinstance(email, dict) or not isinstance(evidence, dict):
        return None
    message_id = _bounded(email.get("message_id"), 500)
    quotation = _bounded(evidence.get("quote"), 10_000)
    if not message_id or evidence.get("message_id") != message_id or not quotation:
        return None
    attachment_id = evidence.get("attachment_id")
    source = email.get("body_excerpt")
    source_url = _public_url(email.get("source_url"))
    source_name = "E-posta gövdesi"
    if attachment_id is not None:
        attachments = email.get("attachments", [])
        matching = [item for item in attachments if isinstance(item, dict) and item.get("attachment_id") == attachment_id] if isinstance(attachments, list) else []
        if len(matching) != 1:
            return None
        attachment = matching[0]
        source = attachment.get("text_excerpt")
        source_name = _bounded(attachment.get("filename"), 300) or "E-posta eki"
        source_url = _public_url(attachment.get("source_url")) or source_url
    if not isinstance(source, str) or len(source) > 100_000 or quotation not in source:
        return None
    if field in NUMERIC_FIELDS:
        number = _decimal(value)
        if number is None or not _numeric_field_in_quote(numeric_field or field, number, quotation):
            return None
    elif field.startswith("technical_specs."):
        if isinstance(value, (dict, list, bool)) or value is None:
            return None
        if isinstance(value, (int, float, Decimal)):
            if not _number_in_quote(_decimal(value), quotation):
                return None
        elif " ".join(str(value).split()).casefold() not in " ".join(quotation.split()).casefold():
            return None
    elif field in {"currency", "unit"}:
        aliases = {"TRY": ("TRY", "TL", "₺"), "USD": ("USD", "$"), "EUR": ("EUR", "€"),
                   "ADET": ("ADET", "AD.", "PCS"), "KG": ("KG", "KİLOGRAM", "KILOGRAM")}
        if not any(alias.casefold() in quotation.casefold() for alias in aliases.get(str(value).upper(), (str(value),))):
            return None
    elif field in {"price_basis", "vat_basis"}:
        labels = {"vat_exclusive": ("kdv hariç", "vat exclusive", "vat excluded", "vat_exclusive"),
                  "vat_inclusive": ("kdv dahil", "vat inclusive", "vat included", "vat_inclusive"),
                  "including_term_markup": ("vade farkı dahil", "vade farkına da", "anapara ve vade farkı", "including_term_markup"),
                  "principal_only": ("yalnız anapara", "sadece anapara", "anapara üzerinden", "principal_only"),
                  "not_stated": ("belirtilmedi", "not stated", "not_stated")}
        if not any(label in " ".join(quotation.split()).casefold() for label in labels.get(str(value), ())):
            return None
    return {"message_id": message_id, "quote": quotation, "attachment_id": attachment_id,
            "source_name": source_name, "source_url": source_url}


def _value(offer, field, warnings, sources, numeric=False):
    raw = offer.get(field)
    if raw is None or raw == "":
        warnings.append(f"{field}: belirtilmedi")
        return None
    value = _decimal(raw) if numeric else _bounded(raw)
    if value is None or (numeric and value < 0):
        warnings.append(f"{field}: geçersiz değer")
        return None
    source = _evidence(offer, field, value)
    if source is None:
        warnings.append(f"{field}: kaynak alıntısı doğrulanamadı")
        return None
    sources[field] = source
    return value


def _json_numbers(value):
    if isinstance(value, Decimal):
        return format(value, "f")
    if isinstance(value, dict):
        return {key: _json_numbers(item) for key, item in value.items()}
    if isinstance(value, list):
        return [_json_numbers(item) for item in value]
    return value


def _same_spec(actual, expected):
    # Eşdeğer kalite veya alternatif standart yorumlanmaz; sadece aynı beyan eşleşir.
    if isinstance(actual, (int, float, Decimal)) and not isinstance(actual, bool):
        return _decimal(actual) == _decimal(expected)
    return " ".join(str(actual).split()).casefold() == " ".join(str(expected).split()).casefold()


def _analyze_offer(offer, request, as_of, deadline):
    warnings, sources = [], {}
    email = offer.get("email") if isinstance(offer.get("email"), dict) else {}
    received = _instant(email.get("received_at"))
    usable_email = bool(_bounded(email.get("message_id"), 500) and received and as_of and received <= as_of
                        and _bounded(email.get("sender"), 500))
    result = {"id": _bounded(offer.get("id"), 120), "supplier": _bounded(offer.get("supplier"), 200),
              "email": {"message_id": _bounded(email.get("message_id"), 500), "received_at": email.get("received_at"),
                        "sender": _bounded(email.get("sender"), 500), "subject": _bounded(email.get("subject"), 1000),
                        "body_excerpt": _bounded(email.get("body_excerpt"), 20_000),
                        "source_url": _public_url(email.get("source_url"))},
              "late": bool(received and deadline and received > deadline), "sources": sources,
              "warnings": warnings, "technical_specs": {}, "required_specs_missing": [], "required_specs_mismatched": []}
    if not usable_email:
        warnings.append("E-posta kimliği/göndereni veya saat dilimli alınma tarihi doğrulanamadı; teklif hesaplamaya alınmadı.")
    fields = {field: _value(offer, field, warnings, sources, field in NUMERIC_FIELDS)
              for field in ("quantity", "unit", "currency", "cash_unit_price", "term_unit_price", "term_days",
                            "vat_rate_pct", "vat_basis", "price_basis", "delivery_days")}
    if fields["price_basis"] not in PRICE_BASES:
        fields["price_basis"] = None
    if fields["vat_basis"] not in VAT_BASES:
        fields["vat_basis"] = None
    rate = fields["vat_rate_pct"]
    if rate is not None and rate > 100:
        warnings.append("KDV oranı geçersiz; yüzde 0–100 aralığında olmalıdır.")
        fields["vat_rate_pct"] = rate = None
    specs = offer.get("technical_specs", {})
    if isinstance(specs, dict) and len(specs) <= 50:
        for key, value in specs.items():
            if not _bounded(key, 200) or isinstance(value, (dict, list)) or value is None:
                continue
            source = _evidence(offer, f"technical_specs.{key}", value)
            if source:
                result["technical_specs"][key] = value
                sources[f"technical_specs.{key}"] = source
            else:
                warnings.append(f"technical_specs.{key}: kaynak alıntısı doğrulanamadı; yayımlanmadı")
    required = request.get("required_specs", {})
    for key, expected in required.items():
        if key not in result["technical_specs"]:
            result["required_specs_missing"].append(key)
        elif not _same_spec(result["technical_specs"][key], expected):
            result["required_specs_mismatched"].append(key)
    result["spec_status"] = ("uygunsuz" if result["required_specs_mismatched"] else "eksik" if result["required_specs_missing"]
                             else "uygun" if required else "şartname belirtilmedi")
    material_matches = bool(offer.get("material_code") == request.get("material_code") and request.get("material_code"))
    scope_matches = bool(material_matches and fields["quantity"] is not None and fields["quantity"] > 0
                         and fields["quantity"] == _decimal(request.get("quantity")) and fields["unit"] == request.get("unit"))
    if not scope_matches:
        warnings.append("Malzeme kodu, miktar veya birim talep kapsamıyla aynı değil; sıralamaya alınmaz.")
    result.update(fields)
    result.update({key: None for key in ("cash_unit_ex_vat", "term_unit_ex_vat", "cash_total_ex_vat", "term_total_ex_vat",
                                        "cash_total_gross", "term_total_gross", "cash_vat_total", "term_vat_total",
                                        "term_markup_amount", "term_markup_percent", "monthly_simple_percent", "monthly_effective_percent")})
    cash, term, quantity = fields["cash_unit_price"], fields["term_unit_price"], fields["quantity"]
    cash_ex = term_ex = cash_gross = term_gross = None
    basis, price_basis = fields["vat_basis"], fields["price_basis"]
    eligible_math = bool(usable_email and scope_matches and fields["currency"])
    both_prices = cash is not None and term is not None
    if eligible_math and price_basis == "vat_exclusive":
        cash_ex, term_ex = cash, term
        if rate is not None:
            cash_gross = cash * (1 + rate / 100) if cash is not None else None
            if term is not None and (basis == "including_term_markup" or (both_prices and cash == term) or rate == 0):
                term_gross = term * (1 + rate / 100)
            elif both_prices and basis == "principal_only":
                term_gross = term + cash * rate / 100
    elif eligible_math and price_basis == "vat_inclusive" and rate is not None:
        cash_gross, term_gross = cash, term
        cash_ex = cash / (1 + rate / 100) if cash is not None else None
        if term is not None and (basis == "including_term_markup" or (both_prices and cash == term) or rate == 0):
            term_ex = term / (1 + rate / 100)
        elif both_prices and basis == "principal_only":
            term_ex = term - (cash - cash_ex)
    if eligible_math and not (both_prices and cash == term) and basis not in {"including_term_markup", "principal_only"} and rate != 0:
        warnings.append("Vade farkının KDV matrahına dahil edilip edilmediği belirtilmedi; belirsiz KDV hesabı yapılmadı.")
    if basis == "principal_only":
        warnings.append("KDV matrahı yalnız anapara: tedarikçi beyanı kıyaslandı; hukuki uygunluk teyidi değildir, firma onayı gerekir.")
    if eligible_math and both_prices and term < cash:
        warnings.append("Vadeli fiyat peşin fiyatın altında; indirim/koşul teyidi gerekir.")
    if eligible_math and price_basis not in {"vat_exclusive", "vat_inclusive"}:
        warnings.append("Fiyatın KDV dahil/hariç olduğu belirtilmedi; toplam hesaplanmadı.")
    result.update({"cash_unit_ex_vat": cash_ex, "term_unit_ex_vat": term_ex,
                   "cash_total_ex_vat": cash_ex * quantity if cash_ex is not None else None,
                   "term_total_ex_vat": term_ex * quantity if term_ex is not None else None,
                   "cash_total_gross": cash_gross * quantity if cash_gross is not None else None,
                   "term_total_gross": term_gross * quantity if term_gross is not None else None,
                   "cash_vat_total": (cash_gross - cash_ex) * quantity if cash_gross is not None and cash_ex is not None else None,
                   "term_vat_total": (term_gross - term_ex) * quantity if term_gross is not None and term_ex is not None else None})
    if cash_ex is not None and term_ex is not None:
        result["term_markup_amount"] = (term_ex - cash_ex) * quantity
        if cash_ex > 0:
            markup = (term_ex / cash_ex - 1) * 100
            result["term_markup_percent"] = markup
            days = fields["term_days"]
            if days is not None and 1 <= days <= 36_500:
                result["monthly_simple_percent"] = markup * 30 / days
                with localcontext() as context:
                    context.prec = 28
                    try:
                        effective = ((term_ex / cash_ex) ** (Decimal(30) / days) - 1) * 100
                        if effective.is_finite() and abs(effective) < Decimal("1e12"):
                            result["monthly_effective_percent"] = effective
                    except (DecimalException, OverflowError):
                        pass
            elif days == 0 and cash_ex != term_ex:
                warnings.append("Sıfır gün vadede fiyat farkı var; aylık oran hesaplanmadı.")
            elif days is not None and (days < 1 or days > 36_500):
                warnings.append("Vade süresi 1–36500 gün dışında; aylık oran karşılaştırması yapılmadı.")
    missing = offer.get("missing_fields", [])
    if isinstance(missing, list):
        warnings.extend("Tedarikçi bilgisi eksik: " + item for item in missing if _bounded(item, 200))
    result["comparable"] = bool(usable_email and scope_matches and fields["currency"] and result["term_total_gross"] is not None
                                and result["spec_status"] not in {"eksik", "uygunsuz"} and not result["late"])
    return result


def analyze_case(case_data):
    """Saf hesap; ağ, takvim veya gönderim işlemi gerçekleştirmez."""
    if isinstance(case_data, dict):
        payload = case_data
        if len(json.dumps(payload, ensure_ascii=False)) > 500_000:
            raise ValueError("Teklif dosyası boyut sınırını aşıyor.")
    else:
        text = _text(case_data)
        if MARKER not in text:
            raise ValueError("TEKLİF DOSYASI (JSON) işareti bulunamadı.")
        try:
            payload = json.loads(text.rsplit(MARKER, 1)[1])
        except (ValueError, TypeError) as error:
            raise ValueError("Teklif dosyası JSON biçimi geçersiz.") from error
    if not isinstance(payload, dict) or not isinstance(payload.get("request"), dict):
        raise ValueError("Talep bilgisi bulunamadı.")
    request = payload["request"]
    required = request.get("required_specs", {})
    offers = payload.get("offers", [])
    if not isinstance(required, dict) or len(required) > 50 or not isinstance(offers, list) or len(offers) > 100:
        raise ValueError("Şartname veya teklif listesi geçersiz ya da sınırın üzerinde.")
    if any(not _bounded(key, 200) or isinstance(value, (dict, list, bool)) or value is None for key, value in required.items()):
        raise ValueError("Teknik şartname alanları sade metin veya sayı olmalıdır.")
    if any(not isinstance(offer, dict) for offer in offers):
        raise ValueError("Her teklif bir JSON nesnesi olmalıdır.")
    as_of, deadline = _instant(payload.get("as_of")), _instant(request.get("deadline_at"))
    status = "final" if (as_of and deadline and as_of >= deadline and request.get("state") in FINAL_STATES) else "preliminary"
    warnings = []
    if as_of is None:
        warnings.append("Rapor zamanı eksik veya saat dilimi yok; teklif hesapları engellendi.")
    if deadline is None:
        warnings.append("Araştırma süresi/son tarih henüz belirlenmedi; ilgili kişiden süre istenmeli.")
    elif as_of and as_of < deadline:
        warnings.append("Araştırma süresi devam ediyor; bu bir ön değerlendirmedir.")
    elif request.get("state") not in FINAL_STATES:
        warnings.append("Süre dolmuş olsa da iş akışı tamamlanmadı; rapor ön değerlendirmedir.")
    rows = [_analyze_offer(offer, request, as_of, deadline) for offer in offers]
    ids = [row["id"] for row in rows]
    duplicate_ids = {item for item in ids if item is None or ids.count(item) > 1}
    messages = [row["email"]["message_id"] for row in rows]
    duplicate_messages = {item for item in messages if item is not None and messages.count(item) > 1}
    for row in rows:
        if row["id"] in duplicate_ids or row["email"]["message_id"] in duplicate_messages:
            row["comparable"] = False
            row["warnings"].append("Teklif kimliği eksik/yinelenmiş veya e-posta birden çok teklif olarak sayılmış; sıralama engellendi.")
    groups = {}
    for row in rows:
        if row["comparable"]:
            groups.setdefault((row["currency"], row["unit"], str(row["quantity"])), []).append(row)
    rankings = []
    for (currency, unit, quantity), group in groups.items():
        ordered = sorted(group, key=lambda row: row["term_total_gross"])
        rankings.append({"currency": currency, "unit": unit, "quantity": quantity,
                         "offer_ids": [row["id"] for row in ordered]})
    if len({row["currency"] for row in rows if row["currency"]}) > 1:
        warnings.append("Farklı para birimleri kur varsayımıyla birleştirilmedi; ayrı gruplarda kıyaslandı.")
    if not required:
        warnings.append("Teknik şartname belirtilmedi; finansal sıralama satın alma önerisi değildir.")
    recommended = None
    if status == "final" and required and len(rankings) == 1 and len(rankings[0]["offer_ids"]) >= 2:
        eligible = [row for row in rows if row["id"] in rankings[0]["offer_ids"]]
        if (len({row["term_days"] for row in eligible}) == 1
                and all(row["term_days"] is not None and row["cash_unit_ex_vat"] is not None and row["term_unit_ex_vat"] is not None
                        and row["vat_basis"] == "including_term_markup" for row in eligible)):
            recommended = rankings[0]["offer_ids"][0]
        else:
            warnings.append("Vadeler/fiyat kapsamı aynı değil, eksik veya KDV matrahı teyit gerektiriyor; düşük brüt toplam tek başına kazanan seçtirmez.")
    return _json_numbers({"request": request, "as_of": payload.get("as_of"), "report_status": status, "sent": False,
                          "offers": rows, "rankings": rankings, "recommended_offer_id": recommended, "warnings": warnings,
                          "monthly_method": "30 gün normalizasyonu; basit oran = toplam fark yüzdesi × 30/vade günü; efektif oran = (vadeli/peşin)^(30/vade günü) − 1"})


